import sys,re
for path in sys.argv[1:]:
    s=open(path,encoding='utf8').read()
    def rep(a,b,n=1):
        global s
        assert s.count(a)==n,(path,a[:70],s.count(a))
        s=s.replace(a,b)
    # ---- 1. grande anguille (jeux) : corps plein qui s'affine, tête large et plate, nageoire pectorale ("oreille"), longue dorsale, marbrures, ventre clair
    i=s.index("function eelSVG(c,d){"); j=s.index("`; }",i)+4
    s=s[:i]+r"""function eelPath(xh,xt,y0,amp,phase,tMax,waves,edge){ const N=20, top=[], bot=[]; for(let k=0;k<=N;k++){ const u=k/N, x=xh+(xt-xh)*u, y=y0+amp*u*Math.sin(phase+u*Math.PI*2*waves), t=tMax*(u<.1 ? .78+u*2.2 : u<.5 ? 1 : Math.pow(1-(u-.5)/.5,.65))+.5; top.push([x,y-t]); bot.push([x,y+t]); }
  const f=p=>p[0].toFixed(1)+' '+p[1].toFixed(1); if(edge==='top') return 'M'+top.map(f).join(' L'); if(edge==='bot') return 'M'+bot.map(f).join(' L'); return 'M'+top.map(f).join(' L')+' L'+bot.reverse().map(f).join(' L')+'Z'; }
function eelSVG(c,d){ const P=(e,ph)=>eelPath(22,148,17,5.5,ph,7,1.15,e), an=(e)=>RM?'':`<animate attributeName="d" dur="2.8s" repeatCount="indefinite" values="${[0,1,2,3,4].map(k=>P(e,-k*Math.PI/2)).join(';')}"/>`;
  const spots=[[34,14,2.2],[42,19,1.8],[50,13.5,2],[58,18,2.2],[66,14,1.7],[74,18.5,1.9],[83,15,1.6],[30,19.5,1.5],[46,16,1.2]].map(q=>`<ellipse cx="${q[0]}" cy="${q[1]}" rx="${q[2]}" ry="${(q[2]*.7).toFixed(1)}" fill="#000" opacity=".28"/>`).join('');
  return `<svg viewBox="0 0 150 34" aria-hidden="true"><path d="${P('top',0)}" fill="none" stroke="${c}" stroke-width="5" stroke-linecap="round" opacity=".55" transform="translate(6 -2.2)">${an('top')}</path><path d="${P('',0)}" fill="${c}" stroke="#000" stroke-opacity=".25" stroke-width=".6" stroke-linejoin="round">${an('')}</path><path d="${P('bot',0)}" fill="none" stroke="${d}" stroke-width="2.6" stroke-linecap="round" opacity=".65" transform="translate(0 -1.6)">${an('bot')}</path>${spots}
    <path d="M24 10 C18 8.5 9 9.5 4 13.5 C1.5 15.5 1.5 18 3 19.5 C8 24.5 18 25.5 24 24Z" fill="${c}" stroke="#000" stroke-opacity=".25" stroke-width=".6"/><path d="M3 19.6 C8 23.6 16 24.6 22 23.6" fill="none" stroke="${d}" stroke-width="2.2" stroke-linecap="round" opacity=".7"/><path d="M2.4 17.6 Q8 19.6 14.5 18.6" fill="none" stroke="#000" stroke-opacity=".5" stroke-width=".9" stroke-linecap="round"/><circle cx="9.6" cy="13.6" r="1.9" fill="#fff"/><circle cx="9.3" cy="13.6" r="1.2" fill="#3F8FC8"/><circle cx="9.1" cy="13.6" r=".55" fill="#111"/><circle cx="4.2" cy="14.6" r=".5" fill="#000" opacity=".5"/>
    <ellipse cx="29" cy="20.5" rx="5.6" ry="3.6" transform="rotate(28 29 20.5)" fill="${d}" stroke="#D9B84A" stroke-width=".9" opacity=".95"/><path d="M26 19.5 l5 2.6 M27 21.6 l3.6 1.4" stroke="${c}" stroke-width=".6" opacity=".6"/></svg>`; }"""+s[j:]
    # ---- 2. petites anguilles du décor rivière (vues du dessus) : corps effilé, tête plate, deux nageoires pectorales
    rep("""const a='M-24 0 Q-18 -5 -12 0 T0 0 T12 0', b='M-24 0 Q-18 5 -12 0 T0 0 T12 0';""","""const a=eelPath(12,-34,0,6,0,3,1.25), b=eelPath(12,-34,0,6,Math.PI,3,1.25);""")
    rep('values="${a};${b};${a}"','values="${[0,1,2,3,4].map(k=>eelPath(12,-34,0,6,-k*Math.PI/2,3,1.25)).join(\';\')}"')
    i=s.index("""<g transform="scale(${sc})"><path d="${a}" fill="none" stroke="#3E3226" stroke-width="6.5" stroke-linecap="round">${wig()}</path>"""); j=s.index("</g></g>`; };",i)
    s=s[:i]+"""<g transform="scale(${sc})"><ellipse cx="7" cy="-4.4" rx="3.6" ry="2" transform="rotate(-32 7 -4.4)" fill="#8A765A" stroke="#C9A94A" stroke-width=".5"/><ellipse cx="7" cy="4.4" rx="3.6" ry="2" transform="rotate(32 7 4.4)" fill="#8A765A" stroke="#C9A94A" stroke-width=".5"/><path d="${a}" fill="#4A3B2C">${wig()}</path><path d="M11 -3.8 C17 -4.2 21 -2.2 21 0 C21 2.2 17 4.2 11 3.8Z" fill="#4A3B2C"/><circle cx="17" cy="-1.9" r="1.1" fill="#8FD3F4"/><circle cx="17" cy="1.9" r="1.1" fill="#8FD3F4"/>"""+s[j:]
